<!-- 字典管理 -->
<template>
  <div class="dictPage">
    <div class="left">
      <div class="search">
        <el-form class="demo-ruleForm">
          <el-form-item label="字典类型" label-width="80px">
            <el-input v-model="queryParams.dict_name" placeholder="请输入字典类型名称搜索" @input="handleSearch" size="small" />
          </el-form-item>
          <el-form-item label-width="14px">
            <el-button type="primary" @click="handleSearch" size="small" icon="el-icon-search">搜索</el-button>
            <el-button type="primary" @click="openAddDialog" size="small" icon="el-icon-plus">新增</el-button>
          </el-form-item>
        </el-form>
      </div>
      <div class="table">
        <div class="jia_table">
          <el-table :data="tableData" style="width: 100%" :header-cell-style="{ background: '#f9fbff',height:'48.5px',fontSIze:'14px' }" height="95%">
            <el-table-column prop="index" label="序号" width="50">
              <template slot-scope="scope">
                {{ ((Number(queryParams.page)-1)*Number(queryParams.per_page))+scope.$index + 1 }}
              </template>
            </el-table-column>
            <el-table-column prop="type_name" label="类型名称" />
            <el-table-column prop="type_code" label="类型编码" />
            <el-table-column prop="enable" label="是否启用">
              <template slot-scope="scope">
                <el-switch v-model="scope.row.enable" active-value="1" inactive-value="2" @change="handleChangeEnable1(scope.row)" />
              </template>
            </el-table-column>
            <el-table-column label="操作">
              <template slot-scope="scope">
                <el-button type="text" icon="el-icon-search" @click="handleSearchDict(scope.row)" size="small">搜索</el-button>
                <el-button type="text" icon="el-icon-edit" @click="openEditDialog(scope.row)" size="small">编辑</el-button>
                <el-button type="text" icon="el-icon-delete" @click="handleDelete(scope.row.id)" size="small" style="margin-left: 10px;">删除</el-button>
              </template>
            </el-table-column>
          </el-table>
          <!-- 如果没有数据，显示空状态 -->
          <el-empty v-if="tableData.length === 0" image="/static/img/home/placeholder_kong.png" :image-size="307" description="暂时没有数据~"></el-empty>
        </div>
        <div class="page">
          <!-- <el-pagination @current-change="getUserData" @size-change="getUserData" :current-page="queryParams.pageNum" :page-size="queryParams.pageSize" :page-sizes="pagesizes" background layout="total, prev, pager, next, jumper,sizes" :total="total">
          </el-pagination> -->
          <!-- 分页器 -->
          <el-pagination :current-page="queryParams.page" :page-size="queryParams.per_page" :total="total" layout="total, prev, pager, next, jumper,sizes" @current-change="getTableData" @size-change="getTableData" />
        </div>
      </div>

      <!-- 新增/编辑对话框 -->
      <el-dialog :title="isEditing ? '编辑' : '新增'" :visible.sync="dialogVisible" width="600px">
        <el-form :model="formData" :rules="formDataRules" ref="form" label-width="100px" class="dictForm" label-position="top">
          <el-form-item label="类型名称" prop="type_name">
            <el-input v-model="formData.type_name" placeholder="请输入类型名称" />
          </el-form-item>
          <el-form-item label="类型编码" prop="type_code">
            <el-input v-model="formData.type_code" placeholder="请输入类型编码" />
          </el-form-item>
          <el-form-item label="是否启用" prop="enable">
            <el-switch v-model="formData.enable" active-value="1" inactive-value="2" />
          </el-form-item>
          <el-form-item label="描述" prop="description">
            <el-input v-model="formData.description" placeholder="请输入描述" />
          </el-form-item>
        </el-form>
        <span slot="footer" class="dialog-footer">
          <el-button @click="dialogVisible = false">取消</el-button>
          <el-button type="primary" @click="handleSave">保存</el-button>
        </span>
      </el-dialog>
    </div>
    <div class="right">
      <div class="search">
        <span>{{ dictTypeName }}</span>
        &nbsp;&nbsp;
        <el-button type="primary" @click="openAddDialog2" size="small" icon="el-icon-plus">新增</el-button>
      </div>
      <div class="table">
        <div class="jia_table">
          <el-table :data="tableData2" style="width: 100%" :header-cell-style="{ background: '#f9fbff',height:'48.5px',fontSize:'14px' }" height="95%">
            <el-table-column prop="index" label="序号" width="50">
              <template slot-scope="scope">
                {{ ((Number(queryParams2.page)-1)*Number(queryParams2.per_page))+scope.$index + 1 }}
              </template>
            </el-table-column>
            <el-table-column prop="data_label" label="数据标签" />
            <el-table-column prop="data_value" label="数据值" />
            <el-table-column prop="enable" label="是否启用">
              <template slot-scope="scope">
                <el-switch v-model="scope.row.enable" active-value="1" inactive-value="2" @change="handleChangeEnable2(scope.row)" />
              </template>
            </el-table-column>
            <el-table-column prop="remark" label="备注" />
            <el-table-column label="操作">
              <template slot-scope="scope">
                <el-button type="text" icon="el-icon-edit" @click="openEditDialog2(scope.row)" size="small">编辑</el-button>
                <el-button type="text" icon="el-icon-delete" @click="handleDelete2(scope.row.id)" size="small" style="margin-left: 10px;">删除</el-button>
              </template>
            </el-table-column>
          </el-table>
          <!-- 如果没有数据，显示空状态 -->
          <el-empty v-if="tableData2.length === 0" image="/static/img/home/placeholder_kong.png" :image-size="307" description="暂时没有数据~"></el-empty>
        </div>
        <div class="page">
          <!-- <el-pagination @current-change="getUserData" @size-change="getUserData" :current-page="queryParams.pageNum" :page-size="queryParams.pageSize" :page-sizes="pagesizes" background layout="total, prev, pager, next, jumper,sizes" :total="total">
          </el-pagination> -->
          <!-- 分页器 -->
          <el-pagination :current-page="queryParams2.page" :page-size="queryParams2.per_page" :total="total2" layout="total, prev, pager, next, jumper,sizes" @current-change="handleSearchDict" @size-change="handleSearchDict" />
        </div>
      </div>

      <!-- 新增/编辑对话框 -->
      <el-dialog :title="isEditing2 ? '编辑' : '新增'" :visible.sync="dialogVisible2" width="600px">
        <el-form :model="formData2" :rules="formData2Rules" ref="form2" label-width="100px" class="dictForm" label-position="top">
          <!-- 数据标签 -->
          <el-form-item label="数据标签" prop="data_label">
            <el-input v-model="formData2.data_label" placeholder="请输入数据标签" />
          </el-form-item>

          <!-- 数据值 -->
          <el-form-item label="数据值" prop="data_value">
            <el-input v-model="formData2.data_value" placeholder="请输入数据值" />
          </el-form-item>

          <!-- 备注 -->
          <el-form-item label="备注" prop="remark">
            <el-input v-model="formData2.remark" placeholder="请输入备注" />
          </el-form-item>

          <!-- 是否启用 -->
          <el-form-item label="是否启用" prop="enable">
            <el-switch v-model="formData2.enable" active-value="1" inactive-value="2" />
          </el-form-item>

          <!-- 字典标识 -->
          <el-form-item label="字典标识" prop="type_code">
            <el-input v-model="formData2.type_code" placeholder="请输入字典标识" />
          </el-form-item>
        </el-form>
        <span slot="footer" class="dialog-footer">
          <el-button @click="dialogVisible2 = false">取消</el-button>
          <el-button type="primary" @click="handleSave2">保存</el-button>
        </span>
      </el-dialog>
    </div>
  </div>
</template>
  
  <script>
import { Message, MessageBox } from 'element-ui'
import { dictApi } from '@/api/system/dict';
export default {
  name: 'dict',
  data() {
    return {
      /* 左侧数据-开始 */
      tableData: [],
      queryParams: {
        dict_name: '',
        page: 1,
        per_page: 10
      },
      total: 0,
      // 表单数据
      formData: {
        id: null,
        type_code: "",
        type_name: "",
        description: "",
        enable: "1",
      },
      formDataRules: {
        type_name: [
          { required: true, message: '请输入类型名称', trigger: 'blur' }
        ],
        type_code: [
          { required: true, message: '请输入类型编码', trigger: 'blur' },
          { pattern: /^[A-Za-z0-9]+$/, message: '类型编码只能包含字母和数字', trigger: 'blur' }
        ],
        enable: [
          { required: true, message: '请选择是否启用', trigger: 'change' }
        ],
        description: [
          { required: true, message: '请输入描述', trigger: 'blur' },
          { max: 200, message: '描述不能超过200个字符', trigger: 'blur' }
        ]
      },
      // 对话框显示状态
      dialogVisible: false,
      // 是否为编辑模式
      isEditing: false,
      /* 左侧数据-结束 */

      /* 右侧数据-开始 */
      tableData2: [],
      queryParams2: {
        type_code: '',
        page: 1,
        per_page: 10
      },
      total2: 0,
      // 表单数据
      formData2: {
        id: null,
        data_label: "",
        data_value: "",
        remark: "",
        enable: "1",
        type_code: "",
      },
      formData2Rules: {
        data_label: [
          { required: true, message: '请输入数据标签', trigger: 'blur' }
        ],
        data_value: [
          { required: true, message: '请输入数据值', trigger: 'blur' }
        ],
        remark: [
          { required: false, message: '请输入备注', trigger: 'blur' }
        ],
        enable: [
          { required: true, message: '请选择是否启用', trigger: 'change' }
        ],
        type_code: [
          { required: true, message: '请输入字典标识', trigger: 'blur' }
        ]
      },
      // 对话框显示状态
      dialogVisible2: false,
      // 是否为编辑模式
      isEditing2: false,
      //   右侧数据类型
      dictTypeName: '',
      /* 右侧数据-结束 */
    };
  },
  computed: {

  },
  created() {
    this.getTableData();
  },
  mounted() {

  },
  methods: {
    /* 左侧函数-开始 */
    // 获取数据
    getTableData() {
      this.$http.get(dictApi.getDictTypeList, { params: this.queryParams }).then(res => {
        this.tableData = res.data.data_list.data;
        // this.handleSearchDict(res.data.data_list.data[0])
        this.total = res.data.data_list.total_items;
      }).catch(err => {
        console.log(err);
      })
    },
    // 打开新增对话框
    openAddDialog() {
      this.isEditing = false;
      this.formData = { id: null, type_code: "", type_name: "", description: "" }; // 重置表单
      this.dialogVisible = true;
    },
    // 打开编辑对话框
    openEditDialog(row) {
      this.isEditing = true;
      this.formData = { ...row }; // 填充表单数据
      this.dialogVisible = true;
    },
    // 处理保存操作
    handleSave() {
      if (this.$refs.form.validate()) {
        if (this.isEditing) {
          // 编辑
          let formData = new FormData();

          // 遍历 msg 对象，并将键值对添加到 formData 中
          Object.keys(this.formData).forEach(key => {
            formData.append(key, this.formData[key]);
          });
          let config = {
            headers: {
              "Content-Type": "multipart/form-data",
            },
          };

          // 修改
          this.$http.post(dictApi.updataDictType, formData, config).then(res => {
            if (res.data.code == 200) {
              this.$message({
                type: 'success',
                message: res.data.msg
              });
            } else {
              this.$message({
                type: 'warning',
                message: res.data.msg
              });
            }
            this.getTableData();
            this.dialogVisible = false;
          }).catch(err => {
            console.log(err);
            this.dialogVisible = false;
          })
        } else {
          delete this.formData.id;
          let formData = new FormData();

          // 遍历 msg 对象，并将键值对添加到 formData 中
          Object.keys(this.formData).forEach(key => {
            formData.append(key, this.formData[key]);
          });
          let config = {
            headers: {
              "Content-Type": "multipart/form-data",
            },
          };

          // 新增
          this.$http.post(dictApi.addDictType, formData, config).then(res => {
            if (res.data.code == 200) {
              this.$message({
                type: 'success',
                message: res.data.msg
              });
            } else {
              this.$message({
                type: 'warning',
                message: res.data.msg
              });
            }
            this.getTableData();
            this.dialogVisible = false;
          }).catch(err => {
            console.log(err);
            this.dialogVisible = false;
          })
        }
      }
    },
    // 处理删除操作
    handleDelete(id) {
      let msg = { id: id }
      let formData = new FormData();

      // 遍历 msg 对象，并将键值对添加到 formData 中
      Object.keys(msg).forEach(key => {
        formData.append(key, msg[key]);
      });
      let config = {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      };
      MessageBox.confirm('确定删除该字典类型吗？', '提示', {
        type: 'warning'
      }).then(() => {
        this.$http.post(dictApi.deleteDictType, formData, config).then(res => {
          if (res.data.code == 200) {
            this.$message({
              type: 'success',
              message: res.data.msg
            });
          } else {
            this.$message({
              type: 'warning',
              message: res.data.msg
            });
          }
          this.getTableData();
        }).catch(err => {
          console.log(err);
        })
      }).catch(() => {
        Message.info('已取消删除');
      });
    },
    // 处理启用禁用
    handleChangeEnable1(row) {
      let formData = { ...row }
      let form = new FormData();
      // 遍历 msg 对象，并将键值对添加到 formData 中
      Object.keys(formData).forEach(key => {
        form.append(key, formData[key]);
      });
      let config = {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      };
      this.$http.post(dictApi.updataDictType, form, config)
        .then(res => {
          if (res.data.code == 200) {
            this.$message({
              type: 'success',
              message: res.data.msg
            });
          } else {
            this.$message({
              type: 'warning',
              message: res.data.msg
            });
          }
          this.getTableData();
        }).catch(err => {
          console.log(err);
        })
    },
    // 处理搜索
    handleSearch() {
      this.getTableData();
    },
    // 表格中搜索
    handleSearchDict(row) {
      if (row) {
        this.queryParams2.type_code = row.type_code
        this.dictTypeName = row.type_name
        this.$set(this.formData2, 'type_code', row.type_code);
      }
      this.$http.get(dictApi.getDictDataList, {
        params: this.queryParams2
      }).then(res => {
        if (res.data.code == 200) {
          this.tableData2 = res.data.data_list.data
          this.total2 = res.data.data_list.total_items
        } else {
          this.$message({
            type: 'warning',
            message: res.data.msg
          })
        }
      }).catch(rek => {
        console.log(rek)
      })
    },
    /* 左侧函数-结束 */

    /* 右侧函数-开始 */
    // 打开新增对话框
    openAddDialog2() {
      this.isEditing2 = false;
      this.formData2 = {
        id: null,
        type_code: this.formData2.type_code,
        data_label: "",
        data_value: "",
        remark: "",
        enable: "1",
      }; // 重置表单
      this.dialogVisible2 = true;
    },
    // 打开编辑对话框
    openEditDialog2(row) {
      this.isEditing2 = true;
      this.formData2 = { ...row }; // 填充表单数据
      this.dialogVisible2 = true;
    },
    // 处理保存操作
    handleSave2() {
      this.$refs.form2.validate(volid => {
        if (volid) {
          if (this.isEditing2) {
            // 编辑
            let formData = new FormData();

            // 遍历 msg 对象，并将键值对添加到 formData 中
            Object.keys(this.formData2).forEach(key => {
              formData.append(key, this.formData2[key]);
            });
            let config = {
              headers: {
                "Content-Type": "multipart/form-data",
              },
            };

            // 修改
            this.$http.post(dictApi.updataDictData, formData, config).then(res => {
              if (res.data.code == 200) {
                this.$message({
                  type: 'success',
                  message: res.data.msg
                });
              } else {
                this.$message({
                  type: 'warning',
                  message: res.data.msg
                });
              }
              this.handleSearchDict();
              this.dialogVisible2 = false;
            }).catch(err => {
              console.log(err);
              this.dialogVisible2 = false;
            })
          } else {
            delete this.formData2.id;
            let formData = new FormData();

            // 遍历 msg 对象，并将键值对添加到 formData 中
            Object.keys(this.formData2).forEach(key => {
              formData.append(key, this.formData2[key]);
            });
            let config = {
              headers: {
                "Content-Type": "multipart/form-data",
              },
            };

            // 新增
            this.$http.post(dictApi.addDictData, formData, config).then(res => {
              if (res.data.code == 200) {
                this.$message({
                  type: 'success',
                  message: res.data.msg
                });
              } else {
                this.$message({
                  type: 'warning',
                  message: res.data.msg
                });
              }
              this.handleSearchDict();
              this.dialogVisible2 = false;
            }).catch(err => {
              console.log(err);
              this.dialogVisible2 = false;
            })
          }
        }
      })
    },
    // 处理启用禁用
    handleChangeEnable2(row) {
      let formData = { ...row }
      let form = new FormData();
      // 遍历 msg 对象，并将键值对添加到 formData 中
      Object.keys(formData).forEach(key => {
        form.append(key, formData[key]);
      });
      let config = {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      };
      this.$http.post(dictApi.updataDictData, form, config)
        .then(res => {
          if (res.data.code == 200) {
            this.$message({
              type: 'success',
              message: res.data.msg
            });
          } else {
            this.$message({
              type: 'warning',
              message: res.data.msg
            });
          }
          this.handleSearchDict();
        }).catch(err => {
          console.log(err);
        })
    },
    // 处理删除操作
    handleDelete2(id) {
      let msg = { id: id }
      let formData = new FormData();

      // 遍历 msg 对象，并将键值对添加到 formData 中
      Object.keys(msg).forEach(key => {
        formData.append(key, msg[key]);
      });
      let config = {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      };
      MessageBox.confirm('确定删除该字典类型吗？', '提示', {
        type: 'warning'
      }).then(() => {
        this.$http.post(dictApi.deleteDictData, formData, config).then(res => {
          if (res.data.code == 200) {
            this.$message({
              type: 'success',
              message: res.data.msg
            });
          } else {
            this.$message({
              type: 'warning',
              message: res.data.msg
            });
          }
          this.handleSearchDict();
        }).catch(err => {
          console.log(err);
        })
      }).catch(() => {
        Message.info('已取消删除');
      });
    },
    /* 右侧函数-结束 */
  }
};
  </script>
  
  <style lang="scss" scoped>
.dictPage {
  width: 100%;
  height: 100%;
  position: relative;
  .left {
    position: absolute;
    left: 0;
    top: 0;
    width: 49%;
    height: 100%;
    background-color: #ffffff;
    border-radius: 6px;
    padding: 10px;
    box-sizing: border-box;
    .search {
      height: 70px;
      padding: 16px 18px 0;
      box-sizing: border-box;
      position: relative;
      .demo-ruleForm {
        height: 100%;
        display: flex;
        justify-content: left;
        align-items: center;
        flex-wrap: wrap;
      }
    }
    .table {
      height: 87%;
      position: relative;
      .jia_table {
        height: 100%;
        .el-table {
          height: 100%;
          background-image: url("../../img/home/placeholder_bottom.png");
          background-position: bottom;
          background-size: 100% 60%;
          background-repeat: no-repeat;
        }
        ::v-deep .el-table--border .el-table__cell,
        .el-table__body-wrapper .el-table--border.is-scrolling-left ~ .el-table__fixed {
          border-right: none;
        }
        ::v-deep .el-table__empty-block {
          // display: none !important;
          .el-table__empty-text {
            color: transparent;
          }
        }
        ::v-deep .el-empty {
          width: 307px;
          height: 353px;
          position: absolute;
          top: 50%;
          left: 50%;
          margin-left: -153px;
          margin-top: -176px;
          .el-empty__image img {
            vertical-align: top;
            height: 147%;
            width: 100%;
          }
          .el-empty__description {
            margin-top: 20px;
            margin-right: 70px;
          }
        }
      }
      .page {
        width: 100%;
        height: 33px;
        // background-color: pink;
        text-align: right;
        position: absolute;
        bottom: -21px;
        right: 0;
      }
    }
  }

  .right {
    position: absolute;
    right: 0;
    top: 0;
    width: 49%;
    height: 100%;
    background-color: #ffffff;
    border-radius: 6px;
    padding: 10px;
    box-sizing: border-box;
    .search {
      height: 70px;
      padding: 16px 18px 0;
      box-sizing: border-box;
      position: relative;
      .demo-ruleForm {
        height: 100%;
        display: flex;
        justify-content: left;
        align-items: center;
        flex-wrap: wrap;
      }
    }
    .table {
      height: 87%;
      position: relative;
      .jia_table {
        height: 100%;
        .el-table {
